-- Admin-published snapshots for the manually maintained Low PE screen.
-- The public site reads through its backend; direct Data API access is denied.
create table if not exists public.manual_low_pe_screener_snapshots (
  id bigint generated always as identity primary key,
  as_of date not null,
  created_at timestamptz not null default now(),
  row_count integer not null check (row_count > 0 and row_count <= 5000),
  rows jsonb not null check (jsonb_typeof(rows) = 'array' and jsonb_array_length(rows) = row_count),
  published_by uuid
);

create index if not exists manual_low_pe_screener_snapshots_latest_idx
  on public.manual_low_pe_screener_snapshots (id desc);

alter table public.manual_low_pe_screener_snapshots enable row level security;
revoke all on public.manual_low_pe_screener_snapshots from anon, authenticated;
revoke all on sequence public.manual_low_pe_screener_snapshots_id_seq from anon, authenticated;

-- Initial administrator-supplied snapshot (two CSV exports, 100 + 28 unique ISINs).
insert into public.manual_low_pe_screener_snapshots (as_of, row_count, rows)
